-- CATALOG-OBJECTCOUNTS-DEV-CRCA | connection snowflakenonprodmcp-012d | read only
SELECT 'VIEWS' k, TABLE_SCHEMA s, COUNT(*) n FROM D01_CRCA.INFORMATION_SCHEMA.VIEWS GROUP BY 2 UNION ALL SELECT 'PROCEDURES', PROCEDURE_SCHEMA, COUNT(*) FROM D01_CRCA.INFORMATION_SCHEMA.PROCEDURES GROUP BY 2 UNION ALL SELECT 'FUNCTIONS', FUNCTION_SCHEMA, COUNT(*) FROM D01_CRCA.INFORMATION_SCHEMA.FUNCTIONS GROUP BY 2 UNION ALL SELECT 'SEQUENCES', SEQUENCE_SCHEMA, COUNT(*) FROM D01_CRCA.INFORMATION_SCHEMA.SEQUENCES GROUP BY 2 UNION ALL SELECT 'STAGES', STAGE_SCHEMA, COUNT(*) FROM D01_CRCA.INFORMATION_SCHEMA.STAGES GROUP BY 2 UNION ALL SELECT 'FILE_FORMATS', FILE_FORMAT_SCHEMA, COUNT(*) FROM D01_CRCA.INFORMATION_SCHEMA.FILE_FORMATS GROUP BY 2 UNION ALL SELECT 'PIPES', PIPE_SCHEMA, COUNT(*) FROM D01_CRCA.INFORMATION_SCHEMA.PIPES GROUP BY 2 ORDER BY 1,2;
